from pathlib import Path
import base64, zlib

ROOT = Path(__file__).resolve().parent
PAYLOAD = ""
runtime = ROOT / "_render_third_exact_runtime.py"
runtime.write_bytes(zlib.decompress(base64.b64decode(PAYLOAD)))
ns = {"__name__": "__main__", "__file__": str(runtime)}
exec(compile(runtime.read_text(encoding="utf-8"), str(runtime), "exec"), ns)
